'use client'

import { CircleAlert } from 'lucide-react'
import type { FormEvent, ReactNode } from 'react'

import { Alert, AlertDescription } from '../../components/ui/alert'
import { Button } from '../../components/ui/button'
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '../../components/ui/card'
import { Checkbox } from '../../components/ui/checkbox'
import {
  Field,
  FieldDescription,
  FieldGroup,
  FieldLabel,
} from '../../components/ui/field'
import { Input } from '../../components/ui/input'

export type AuthFormField = {
  id: string
  label: string
  type?: 'text' | 'email' | 'password'
  placeholder?: string
  autoComplete?: string
  value?: string
  defaultValue?: string
  onChange?: (value: string) => void
  required?: boolean
  disabled?: boolean
  description?: string
}

export type AuthFormRemember = {
  id: string
  label: string
  checked?: boolean
  defaultChecked?: boolean
  onCheckedChange?: (checked: boolean) => void
  disabled?: boolean
}

export type AuthForm01Props = {
  title: string
  description?: string
  /** The credential fields, in order. */
  fields: AuthFormField[]
  /** An error message shown above the fields and marked on each control. */
  error?: string
  /** A remember-me row under the fields. */
  remember?: AuthFormRemember
  /** The submit button label. */
  submitLabel: string
  /** The label shown while `pending` is true. Falls back to `submitLabel`. */
  pendingLabel?: string
  /** Disables the submit control while a request is in flight. */
  pending?: boolean
  onSubmit?: (event: FormEvent<HTMLFormElement>) => void
  /** A row under the submit button, e.g. a link to another screen. */
  footer?: ReactNode
}

/**
 * A sign-in card.
 *
 * The block renders the card, the labelled fields, the remember row and the
 * submit control. It owns no credentials and no request: every field value and
 * the submit handler come from the consumer, and the error line is a prop so
 * the consumer's validation decides when it appears. Every string is a prop.
 */
export function AuthForm01({
  title,
  description,
  fields,
  error,
  remember,
  submitLabel,
  pendingLabel,
  pending = false,
  onSubmit,
  footer,
}: AuthForm01Props) {
  return (
    <form onSubmit={onSubmit} className="w-full">
      <Card>
        <CardHeader>
          <CardTitle>{title}</CardTitle>
          {description ? <CardDescription>{description}</CardDescription> : null}
        </CardHeader>

        <CardContent className="flex flex-col gap-4">
          {error ? (
            <Alert variant="destructive">
              <CircleAlert />
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          ) : null}

          <FieldGroup>
            {fields.map((field) => (
              <Field key={field.id}>
                <FieldLabel htmlFor={field.id}>{field.label}</FieldLabel>
                <Input
                  id={field.id}
                  type={field.type ?? 'text'}
                  placeholder={field.placeholder}
                  autoComplete={field.autoComplete}
                  value={field.value}
                  defaultValue={field.defaultValue}
                  onChange={
                    field.onChange
                      ? (event) => field.onChange?.(event.target.value)
                      : undefined
                  }
                  required={field.required}
                  disabled={field.disabled}
                  aria-invalid={error ? true : undefined}
                />
                {field.description ? (
                  <FieldDescription>{field.description}</FieldDescription>
                ) : null}
              </Field>
            ))}
          </FieldGroup>

          {remember ? (
            <div className="flex items-center gap-2">
              <Checkbox
                id={remember.id}
                checked={remember.checked}
                defaultChecked={remember.defaultChecked}
                onCheckedChange={remember.onCheckedChange}
                disabled={remember.disabled}
              />
              <FieldLabel htmlFor={remember.id}>{remember.label}</FieldLabel>
            </div>
          ) : null}
        </CardContent>

        <CardFooter className="flex-col gap-3">
          <Button type="submit" className="w-full" disabled={pending}>
            {pending ? (pendingLabel ?? submitLabel) : submitLabel}
          </Button>
          {footer}
        </CardFooter>
      </Card>
    </form>
  )
}

export default AuthForm01

import type { ReactNode } from 'react'
import { cn } from '../../lib/utils'

/**
 * Container primitive. Every block composes its own section from this so vertical
 * rhythm stays consistent across the catalog instead of being re-invented per block.
 */
export function Section({
  className,
  children,
  ...props
}: React.ComponentProps<'section'>) {
  return (
    <section
      className={cn('py-16 sm:py-24', className)}
      {...props}
    >
      <div className="mx-auto w-full max-w-6xl px-6 lg:px-8">
        {children}
      </div>
    </section>
  )
}

/**
 * The six heading levels a block can be composed at.
 *
 * Every block takes a `headingLevel` prop typed with this and forwards it to the
 * one heading it renders, so the surrounding document decides where the block
 * sits in the outline rather than the block deciding for itself. `h2` is the
 * default because a block is composed, not a page.
 *
 * A block rendered where the document *already* owns a heading for the same
 * content passes one level deeper. A catalog card already names the block in its
 * own `h2`, so the copy of the block embedded inside that card passes `h3`: the
 * embedded heading then reads as a child of the card that introduces it instead
 * of as a second, competing sibling. This is a fact about where the block was
 * placed, not about the block, which is why it is a prop and not a default.
 */
export type HeadingLevel = 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6'

export function SectionHeading({
  eyebrow,
  title,
  as: Heading = 'h2',
  description,
  align = 'center',
  className,
}: {
  eyebrow?: ReactNode
  title: ReactNode
  description?: ReactNode
  align?: 'center' | 'left'
  /**
   * Heading level. Defaults to `h2` because blocks compose under a page heading.
   * A page that renders a block as its primary heading passes `as="h1"`; a
   * document with no `h1` gives screen-reader and search engines no top-level
   * entry point.
   */
  as?: HeadingLevel
  className?: string
}) {
  return (
    <div
      className={cn(
        'flex flex-col gap-4',
        align === 'center' ? 'items-center text-center' : 'items-start text-left',
        className,
      )}
    >
      {eyebrow ? (
        <span className="text-muted-foreground text-sm font-medium tracking-wide uppercase">
          {eyebrow}
        </span>
      ) : null}
      <Heading className="text-3xl font-semibold tracking-tight text-balance sm:text-4xl">
        {title}
      </Heading>
      {description ? (
        <p className="text-muted-foreground max-w-2xl text-lg text-pretty">
          {description}
        </p>
      ) : null}
    </div>
  )
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
